const body = $json.body || $json;

const candidateId = body.candidateId || 'cand_demo_01';
const candidateName = body.name || body.candidateName || 'Đoàn Thanh Huy';
const candidateEmail = body.email || body.candidateEmail || 'doanthanhhuy130978@gmail.com';
const jobTitle = body.jobTitle || 'Senior Fullstack Engineer';
const matchScore = Number(body.matchScore || 85);

// Extract rich skills & tech ATS metadata
const parsed = typeof body.parsedSkillsJson === 'object' && body.parsedSkillsJson !== null ? body.parsedSkillsJson : {};
const combinedFromParsed = (Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0)
  ? [...parsed.coreSkills, ...(Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : [])]
  : (Array.isArray(parsed.skills) ? parsed.skills : null);
const rawSkills = combinedFromParsed || (Array.isArray(body.parsedSkillsJson) ? body.parsedSkillsJson : (Array.isArray(body.skills) ? body.skills : ['Software Engineering']));

const coreSkills = Array.isArray(parsed.coreSkills) && parsed.coreSkills.length > 0 
  ? parsed.coreSkills 
  : (Array.isArray(body.coreSkills) ? body.coreSkills : rawSkills.slice(0, 3));
const secondarySkills = Array.isArray(parsed.secondarySkills) ? parsed.secondarySkills : (Array.isArray(body.secondarySkills) ? body.secondarySkills : rawSkills.slice(3));
const systemScaleScore = Number(parsed.systemScaleScore || body.systemScaleScore || 75);
const githubUrl = parsed.githubUrl || body.githubUrl || null;
const keywordStuffingFlag = Boolean(parsed.keywordStuffingFlag || body.keywordStuffingFlag);
const focusPoints = Array.isArray(parsed.interviewFocusPoints)
  ? parsed.interviewFocusPoints.filter(p => typeof p === 'string' && p.trim().length > 0)
  : [];

// Fallback Question Pool
const fallbackPool = [
  {
    question: `Trong dự án gần nhất ứng dụng ${coreSkills[0] || jobTitle}, bạn đã thiết kế kiến trúc module và tối ưu hóa hiệu năng (caching/query optimization) như thế nào?`,
    targetSkill: coreSkills[0] || 'System Architecture',
    whyAsk: `Thẩm định độ sâu kinh nghiệm thực tế với ${coreSkills[0] || 'công nghệ chính'} và xác minh xem ứng viên trực tiếp thiết kế hay chỉ kế thừa mã nguồn.`,
    goodAnswerSignals: `Ứng viên đưa ra được số liệu cụ thể (latency, QPS), giải thích rõ ràng Trade-off và kiến trúc module hợp lý.`
  },
  {
    question: `Khi hệ thống đối mặt với tình trạng lưu lượng tăng đột biến gây nghẽn cơ sở dữ liệu hoặc trễ phản hồi, bạn tiến hành điều tra và xử lý sự cố theo các bước cụ thể nào?`,
    targetSkill: 'High Concurrency & Fault Tolerance',
    whyAsk: `Kiểm tra tư duy phản ứng sự cố (Incident Response) và kiểm chứng điểm System Scale (${systemScaleScore}/100) được ghi nhận từ vòng hồ sơ.`,
    goodAnswerSignals: `Trình bày mạch lạc về profiling, slow query log, Redis caching, connection pool, rate limiting hoặc queue worker.`
  },
  {
    question: focusPoints[0] || `Bạn tiếp cận việc viết Unit/Integration Tests và thiết lập quy trình CI/CD để đảm bảo chất lượng phần mềm trong dự án thực tế như thế nào?`,
    targetSkill: coreSkills[1] || 'Code Quality & Testing',
    whyAsk: focusPoints[0] ? 'Làm rõ điểm trọng tâm cần kiểm chứng trong hồ sơ theo khuyến nghị của AI Screener.' : 'Đánh giá tính kỷ luật kỹ thuật và tư duy kiểm thử tự động của ứng viên trước khi release sản phẩm.',
    goodAnswerSignals: focusPoints[0] ? 'Nêu rõ bối cảnh sự cố, phương án khắc phục và bài học kinh nghiệm sau khi triển khai lên môi trường Production.' : 'Nắm rõ test pyramid, mocking, automation pipeline (GitHub Actions/GitLab CI) và code coverage thực tế.'
  }
];

let interviewKit = Array.isArray(parsed.interviewKit) && parsed.interviewKit.length > 0 ? parsed.interviewKit : fallbackPool;

const skills = rawSkills;
const skillsStr = Array.isArray(skills) ? skills.join(', ') : String(skills);
const companyName = body.companyName || 'Công ty Cổ phần Công nghệ HR Tech Hub';

// Phân bổ Ban Phỏng Vấn thông minh dựa trên Job Title & Kỹ năng
let leadInterviewer = {
  name: 'Đoàn Thanh Huy',
  role: 'AI Recruitment Squad Lead',
  email: 'doanthanhhuy1309@gmail.com',
  phone: '0901 234 567'
};

const jobLower = (jobTitle + ' ' + skillsStr).toLowerCase();
if (jobLower.includes('python') || jobLower.includes('backend') || jobLower.includes('c++') || jobLower.includes('security')) {
  leadInterviewer = {
    name: 'Nguyễn Hoàng Nam',
    role: 'Principal Software Architect & Security Lead',
    email: 'nam.nguyen@company.com',
    phone: '0912 345 678'
  };
} else if (jobLower.includes('frontend') || jobLower.includes('react') || jobLower.includes('ui') || jobLower.includes('mobile')) {
  leadInterviewer = {
    name: 'Trần Thị Mai',
    role: 'Lead Frontend & Mobile Architect',
    email: 'mai.tran@company.com',
    phone: '0983 210 987'
  };
} else if (jobLower.includes('test') || jobLower.includes('qa') || jobLower.includes('qc')) {
  leadInterviewer = {
    name: 'Lê Quốc Huy',
    role: 'Head of Quality Assurance & Automation',
    email: 'huy.le@company.com',
    phone: '0934 567 890'
  };
}

// Thuật toán tính ngày làm việc (tránh Thứ 7 & Chủ Nhật)
let workingDaysToAdd = 3;
let targetDate = new Date();
while (workingDaysToAdd > 0) {
  targetDate.setDate(targetDate.getDate() + 1);
  const dayOfWeek = targetDate.getDay();
  if (dayOfWeek !== 0 && dayOfWeek !== 6) {
    workingDaysToAdd--;
  }
}
targetDate.setHours(9, 30, 0, 0);

const endDate = new Date(targetDate.getTime() + 60 * 60 * 1000);
const formattedDate = targetDate.toLocaleDateString('vi-VN', {
  weekday: 'long',
  year: 'numeric',
  month: 'numeric',
  day: 'numeric'
});
const formattedTime = '09:30 - 10:30 (Giờ Việt Nam)';
const dateTimeFormatted = `${formattedTime}, ${formattedDate}`;

const deadlineDate = new Date(targetDate);
deadlineDate.setDate(deadlineDate.getDate() - 1);
if (deadlineDate.getDay() === 0) deadlineDate.setDate(deadlineDate.getDate() - 2);
if (deadlineDate.getDay() === 6) deadlineDate.setDate(deadlineDate.getDate() - 1);
const deadlineFormatted = `17:00 ngày ${deadlineDate.toLocaleDateString('vi-VN', { year: 'numeric', month: 'numeric', day: 'numeric' })} (24 giờ trước buổi phỏng vấn)`;

const interviewType = (body.interviewType || body.type || body.format || 'ONLINE').toUpperCase();
const isOnline = !interviewType.includes('OFF') && !interviewType.includes('TRỰC TIẾP') && !interviewType.includes('TRUC TIEP') && !interviewType.includes('ONSITE');

const randomRoomId = Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 6) + '-' + Math.random().toString(36).substring(2, 5);
const fallbackMeetUrl = body.meetingUrl || body.googleMeetUrl || `https://meet.google.com/${randomRoomId}`;
const officeAddress = body.address || body.location || 'Tòa nhà HR Tech Tower, Tầng 8, 123 Đường Nam Kỳ Khởi Nghĩa, Quận 1, TP. Hồ Chí Minh';

const contactPerson = {
  name: body.contactPersonName || leadInterviewer.name,
  phone: body.contactPersonPhone || leadInterviewer.phone || '0901 234 567',
  email: body.contactPersonEmail || leadInterviewer.email || 'recruitment@company.com'
};
const contactText = `${contactPerson.name} - SĐT: ${contactPerson.phone} / Email: ${contactPerson.email}`;

const sender = {
  name: body.senderName || 'Đoàn Thanh Huy',
  role: body.senderRole || body.senderTitle || 'Trưởng Ban Tuyển Dụng & AI Sourcing Lead',
  company: companyName,
  contact: body.senderContact || 'Email: doanthanhhuy1309@gmail.com | Hotline: 0901 234 567'
};

const calendarSummary = `Phỏng vấn tuyển dụng ${jobTitle} – ${candidateName}`;
const calendarDescription = `Phỏng vấn vị trí ${jobTitle} tại ${companyName}.\nNgười phỏng vấn: ${leadInterviewer.name} (${leadInterviewer.role})\nNgười liên hệ: ${contactText}`;

return [{
  json: {
    candidateId,
    candidateName,
    candidateEmail,
    jobTitle,
    matchScore,
    skills,
    coreSkills,
    secondarySkills,
    systemScaleScore,
    githubUrl,
    keywordStuffingFlag,
    interviewKit,
    companyName,
    leadInterviewer,
    targetDate: targetDate.toISOString(),
    endDate: endDate.toISOString(),
    formattedDate,
    formattedTime,
    dateTimeFormatted,
    deadlineFormatted,
    interviewType,
    isOnline,
    fallbackMeetUrl,
    officeAddress,
    contactPerson,
    contactText,
    sender,
    calendarSummary,
    calendarDescription
  }
}];

const data = $json;

const scorecardRubric = [
  {
    pillar: "Technical Depth & Architecture",
    weight: "40%",
    description: "Nắm vững cốt lõi framework, database design, caching, clean code và xử lý concurrency.",
    scoringLevels: {
      excellent: "Hiểu sâu bản chất, thiết kế hệ thống tối ưu, bảo mật cao",
      acceptable: "Nắm vững kiến thức cơ bản đến trung cấp, làm được dự án",
      poor: "Chỉ làm theo mẫu có sẵn, không hiểu sâu bản chất kỹ thuật"
    }
  },
  {
    pillar: "Problem Solving & Analytical Thinking",
    weight: "30%",
    description: "Tư duy bẻ nhỏ bài toán phức tạp, phân tích yêu cầu, xử lý lỗi và edge case logic.",
    scoringLevels: {
      excellent: "Giải quyết bài toán mạch lạc, lường trước các edge case và rủi ro tải",
      acceptable: "Tìm ra giải pháp sau khi được gợi ý định hướng",
      poor: "Bế tắc khi gặp tình huống lạ, tư duy rời rạc"
    }
  },
  {
    pillar: "System Scalability & Production Readiness",
    weight: "20%",
    description: "Hiểu biết về containerization (Docker), CI/CD, logging, monitoring và xử lý chịu tải.",
    scoringLevels: {
      excellent: "Có kinh nghiệm vận hành production thực tế, tư duy scale tốt",
      acceptable: "Biết sử dụng công cụ cơ bản",
      poor: "Chưa từng tiếp cận môi trường production thực tế"
    }
  },
  {
    pillar: "Culture Fit & Communication",
    weight: "10%",
    description: "Giao tiếp kỹ thuật rõ ràng, tinh thần hợp tác Agile, ownership và thái độ học hỏi.",
    scoringLevels: {
      excellent: "Giao tiếp tự tin, cởi mở, tinh thần trách nhiệm cao",
      acceptable: "Giao tiếp ổn định, hòa đồng",
      poor: "Bảo thủ, khó tiếp thu phản hồi kỹ thuật"
    }
  }
];

return [{
  json: {
    ...data,
    scorecardRubric
  }
}];

const data = $json;
const skills = data.skills || [];
const skillsLower = skills.map(s => String(s).toLowerCase());
const targetJobLower = (data.jobTitle || '').toLowerCase();

let miniCodeChallenge;
if (skillsLower.some(s => s.includes('react') || s.includes('vue') || s.includes('angular') || s.includes('next')) || targetJobLower.includes('frontend')) {
  miniCodeChallenge = {
    domain: 'Frontend',
    title: 'Thiết kế Data Grid ảo hóa (Virtualization) và tối ưu Render',
    taskDescription: 'Trình bày cách triển khai danh sách/bảng 10.000 bản ghi trên trình duyệt mượt mà (60 FPS), kết hợp memoization và caching client-side.',
    suggestedDuration: '30-45 phút chuẩn bị / thảo luận'
  };
} else if (skillsLower.some(s => s.includes('docker') || s.includes('kubernetes') || s.includes('aws') || s.includes('ci/cd')) || targetJobLower.includes('devops')) {
  miniCodeChallenge = {
    domain: 'DevOps / Cloud',
    title: 'Thiết kế Pipeline CI/CD Zero-Downtime Deployment & Canary Release',
    taskDescription: 'Trình bày giải pháp rolling update không gián đoạn dịch vụ, chiến lược health check và tự động rollback khi tỷ lệ lỗi > 1%.',
    suggestedDuration: '30-45 phút chuẩn bị / thảo luận'
  };
} else if (skillsLower.some(s => s.includes('test') || s.includes('qa') || s.includes('selenium') || s.includes('playwright')) || targetJobLower.includes('qa') || targetJobLower.includes('test')) {
  miniCodeChallenge = {
    domain: 'QA Automation',
    title: 'Thiết kế Framework Kiểm Thử Tự Động & Chiến lược Quản lý Test Flaky',
    taskDescription: 'Trình bày giải pháp tự động hóa kiểm thử API và E2E, cơ chế cách ly flaky test và tích hợp báo cáo chất lượng vào PR Gate.',
    suggestedDuration: '30-45 phút chuẩn bị / thảo luận'
  };
} else {
  miniCodeChallenge = {
    domain: 'Backend & System Design',
    title: 'Thiết kế Hệ Thống Rate Limiter Phân Tán (Distributed Rate Limiting)',
    taskDescription: 'Trình bày kiến trúc giới hạn tốc độ yêu cầu (1.000 requests/giây/user) sử dụng Redis Token Bucket / Leaky Bucket, đảm bảo tính nhất quán giữa các instance.',
    suggestedDuration: '30-45 phút chuẩn bị / thảo luận'
  };
}

return [{
  json: {
    ...data,
    miniCodeChallenge
  }
}];

const data = $json;
const candidateId = data.candidateId;

const rsvpConfirmUrl = `http://localhost:3001/recruitment/candidates/${candidateId}/rsvp?status=CONFIRMED`;
const rsvpRescheduleUrl = `http://localhost:3001/recruitment/candidates/${candidateId}/rsvp?status=RESCHEDULE_REQUESTED`;
const rsvpStatus = 'PENDING_CONFIRMATION';

return [{
  json: {
    ...data,
    rsvpStatus,
    rsvpConfirmUrl,
    rsvpRescheduleUrl
  }
}];

const intake = $('Smart Interviewer Panel Routing & Schedule Engine').first().json;
const gcalResult = $json;

// Lấy link Google Meet thật từ Google Calendar API nếu có kết nối
const realGoogleMeetUrl = gcalResult?.hangoutLink || 
  (gcalResult?.conferenceData?.entryPoints ? gcalResult.conferenceData.entryPoints[0]?.uri : null) || 
  intake.fallbackMeetUrl;

const isRealGoogleMeet = !!(gcalResult?.hangoutLink || (gcalResult?.conferenceData?.entryPoints && gcalResult.conferenceData.entryPoints[0]?.uri));
const googleCalendarEventId = gcalResult?.id || null;
const googleCalendarHtmlLink = gcalResult?.htmlLink || null;

const isOnline = intake.isOnline;
const officeAddress = intake.officeAddress;
const candidateName = intake.candidateName;
const jobTitle = intake.jobTitle;
const companyName = intake.companyName;
const dateTimeFormatted = intake.dateTimeFormatted;
const deadlineFormatted = intake.deadlineFormatted;
const contactText = intake.contactText;
const sender = intake.sender;

let locationText = '';
let locationHtml = '';

if (isOnline) {
  const demoTag = isRealGoogleMeet ? '' : ' (Demo – link mô phỏng)';
  locationText = `Phòng họp trực tuyến (Google Meet${demoTag}): ${realGoogleMeetUrl}`;
  locationHtml = `<a href="${realGoogleMeetUrl}" style="color: #2563eb; font-weight: 600; text-decoration: underline;">${realGoogleMeetUrl}</a> (Google Meet${demoTag})`;
} else {
  locationText = `Trực tiếp tại văn phòng: ${officeAddress}`;
  locationHtml = `<strong>${officeAddress}</strong>`;
}

// Tiêu đề email chuẩn theo mẫu: "Tiêu đề: Thư mời phỏng vấn – [Tên công ty]"
const emailSubject = `Thư mời phỏng vấn – ${companyName}`;

// Sinh nội dung iCalendar .ics tương thích mọi ứng dụng Calendar
const calendarIcsContent = [
  'BEGIN:VCALENDAR',
  'VERSION:2.0',
  'PRODID:-//HR Tech Corp//AI Recruitment Orchestrator//VI',
  'CALSCALE:GREGORIAN',
  'METHOD:REQUEST',
  'BEGIN:VEVENT',
  `UID:interview-${intake.candidateId}-${Date.now()}@hrtech.platform`,
  `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').split('.')[0]}Z`,
  `DTSTART:${new Date(intake.calendarStartTime).toISOString().replace(/[-:]/g, '').split('.')[0]}Z`,
  `DTEND:${new Date(intake.calendarEndTime).toISOString().replace(/[-:]/g, '').split('.')[0]}Z`,
  `SUMMARY:${intake.calendarSummary}`,
  `DESCRIPTION:${intake.calendarDescription.replace(/\n/g, '\\n')}`,
  `LOCATION:${isOnline ? realGoogleMeetUrl : officeAddress}`,
  'STATUS:CONFIRMED',
  'SEQUENCE:0',
  'END:VEVENT',
  'END:VCALENDAR'
].join('\r\n');


const rsvpConfirmUrl = `http://localhost:3001/recruitment/candidates/${intake.candidateId}/rsvp?status=CONFIRMED`;
const rsvpRescheduleUrl = `http://localhost:3001/recruitment/candidates/${intake.candidateId}/rsvp?status=RESCHEDULE`;
const miniChallenge = intake.miniCodeChallenge || {
  title: 'Trao đổi về kiến trúc dự án và tối ưu hiệu năng',
  taskDescription: 'Chuẩn bị chia sẻ chi tiết về một bài toán kỹ thuật phức tạp nhất bạn từng trực tiếp giải quyết.'
};

const rsvpHtmlBlock = `
  <div style="text-align: center; margin: 24px 0 16px 0;">
    <a href="${rsvpConfirmUrl}" style="display: inline-block; background-color: #16a34a; color: #ffffff; text-decoration: none; font-weight: bold; font-size: 14px; padding: 12px 24px; border-radius: 6px; margin-right: 12px; box-shadow: 0 2px 4px rgba(22, 163, 74, 0.2);">
      ✓ Xác Nhận Tham Gia
    </a>
    <a href="${rsvpRescheduleUrl}" style="display: inline-block; background-color: #f1f5f9; color: #475569; text-decoration: none; font-weight: bold; font-size: 14px; padding: 12px 20px; border-radius: 6px; border: 1px solid #cbd5e1;">
      ⟳ Yêu Cầu Dời Giờ
    </a>
  </div>
`;

const challengeHtmlBlock = `
  <div style="background-color: #f8fafc; border: 1px dashed #cbd5e1; border-radius: 8px; padding: 16px; margin: 20px 0;">
    <h4 style="margin: 0 0 6px 0; color: #0f172a; font-size: 13px; text-transform: uppercase; letter-spacing: 0.5px;">💡 CHỦ ĐỀ KỸ THUẬT CHUẨN BỊ TRAO ĐỔI (MINI TECH CHALLENGE)</h4>
    <p style="margin: 0 0 4px 0; font-size: 13px; font-weight: bold; color: #2563eb;">${miniChallenge.title}</p>
    <p style="margin: 0; font-size: 13px; color: #475569; line-height: 1.5;">${miniChallenge.taskDescription}</p>
  </div>
`;

// Soạn thảo thư mời phỏng vấn theo đúng cấu trúc chuẩn của người dùng
const candidateEmailHtml = `<!DOCTYPE html>
<html>
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"></head>
<body style="font-family: Arial, 'Segoe UI', Helvetica, sans-serif; background-color: #f8fafc; margin: 0; padding: 24px; color: #1e293b; line-height: 1.6;">
  <div style="max-width: 620px; margin: 0 auto; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.06);">
    <div style="background: linear-gradient(135deg, #2563eb 0%, #1d4ed8 100%); height: 8px; width: 100%;"></div>
    <div style="padding: 32px 28px;">

      <p style="margin-top: 0; font-size: 15px; font-weight: 600; color: #0f172a;">Chào bạn ${candidateName},</p>

      <p style="font-size: 14px; color: #334155; margin-bottom: 16px;">
        Cảm ơn bạn đã quan tâm đến cơ hội nghề nghiệp tại <strong>${companyName}</strong>. Chúng tôi rất ấn tượng với hồ sơ của bạn và trân trọng mời bạn tham dự buổi phỏng vấn cho vị trí:
      </p>

      <div style="background-color: #f1f5f9; border-left: 4px solid #2563eb; border-radius: 6px; padding: 16px 18px; margin: 20px 0;">
        <h3 style="margin: 0 0 12px 0; font-size: 16px; color: #0f172a;">🎯 Vị trí ứng tuyển: ${jobTitle}</h3>
        <table style="width: 100%; border-collapse: collapse; font-size: 14px; color: #334155;">
          <tr>
            <td style="padding: 6px 0; width: 110px; font-weight: 600; color: #475569;">⏰ Thời gian:</td>
            <td style="padding: 6px 0; font-weight: 700; color: #0f172a;">${dateTimeFormatted}</td>
          </tr>
          <tr>
            <td style="padding: 6px 0; font-weight: 600; color: #475569;">📍 Địa điểm:</td>
            <td style="padding: 6px 0;">${locationHtml}</td>
          </tr>
        </table>
      </div>
      ${rsvpHtmlBlock}
      ${challengeHtmlBlock}
          <tr>
            <td style="padding: 6px 0; font-weight: 600; color: #475569;">👤 Người PV:</td>
            <td style="padding: 6px 0;"><strong>${intake.leadInterviewer.name}</strong> (${intake.leadInterviewer.role})</td>
          </tr>
        </table>
      </div>

      <p style="font-size: 14px; color: #334155; margin-bottom: 12px;">
        Vui lòng xác nhận sự tham gia của bạn trước <strong>${deadlineFormatted}</strong> bằng cách phản hồi lại email này.
      </p>

      <p style="font-size: 14px; color: #334155; margin-bottom: 24px;">
        Nếu bạn có bất kỳ câu hỏi nào hoặc cần thay đổi thời gian, xin vui lòng liên hệ trực tiếp với: <strong>${contactText}</strong>.
